<?php require __DIR__.'/../lib.php'; require_login(); $db=db(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $email=trim($_POST['site_email']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)) $msg='Bitte eine gültige E-Mail-Adresse eingeben.'; else {$st=$db->prepare("INSERT INTO settings(key,value) VALUES('site_email',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value"); $st->execute([$email]); $msg='E-Mail-Adresse gespeichert.';}} $email=setting('site_email'); ?>
